'use strict';
const {escapeHTML:esc,resolve:coreResolve,record,bookmark,read,BrowserTabs,videoTarget}=ZeroCore;
const $=id=>document.getElementById(id);
const icons={reading:'<path d="M3 5c3-1 6-1 9 1 3-2 6-2 9-1v15c-3-1-6-1-9 1-3-2-6-2-9-1zM12 6v15"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/>',back:'<path d="m14 5-7 7 7 7"/>',forward:'<path d="m10 5 7 7-7 7"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 6a8 8 0 0 1 13 3M18 18A8 8 0 0 1 5 15"/>',home:'<path d="m3 10 9-7 9 7v10H6V10m4 10v-7h4v7"/>',library:'<path d="M4 4h5v16H4zm8 0h4v16h-4zm6 1 3-1 4 15-3 1z"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',history:'<path d="M3 4v5h5"/><path d="M4 8a8 8 0 1 1-1 8m9-9v5l3 2"/>',video:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m10 9 5 3-5 3z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',moon:'<path d="M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10z"/>',external:'<path d="M14 3h7v7m0-7L10 14m0-10H4v16h16v-6"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.search}</svg>`;
const translations={
headline:['少一点，<br>多看见。','Less noise.<br>More web.'],intro:['让浏览，回归浏览。<br>一个输入框，其余留白。','Back to the simple act of browsing.<br>One field. Room for everything else.'],previewNote:['浏览器交互预览<br>原生 iOS 版本开发中','An interactive browser preview.<br>Native iOS app in development.'],caption:['所有复杂，藏于简单之后。','Everything you need. Nothing in the way.'],tryTitle:['从这里开始','TAKE A LOOK AROUND'],trySearch:['随心搜索','Follow your curiosity'],trySearchSub:['输入一个好奇的问题','Start with a question'],tryArticle:['安静地阅读','A little room to read'],tryArticleSub:['打开极简阅读示例','Open the reading demo'],tryVideo:['把片刻留下','Keep a moment'],tryVideoSub:['播放视频，缓存后再看','Play it. Save it. Play it offline.'],guideNote:['底部操作栏，随时触达。<br>切换页面，或打开资料库。','Everything is in the bottom bar.<br>Switch pages or open your library.'],reset:['重置预览数据','Reset preview data']};
let prefs=read(localStorage,'zr-prefs',{});if(!prefs||typeof prefs!=='object')prefs={};
let lang=['zh','en'].includes(prefs.lang)?prefs.lang:(navigator.language.startsWith('zh')?'zh':'en');
let dark=prefs.dark===true;
let bookmarks=read(localStorage,'zr-bookmarks',[]),history=read(localStorage,'zr-history',[]);
bookmarks=Array.isArray(bookmarks)?bookmarks.filter(p=>p&&typeof p.url==='string'&&typeof p.title==='string'):[];
history=Array.isArray(history)?history.filter(p=>p&&typeof p.url==='string'&&typeof p.title==='string'):[];
const sessions=new BrowserTabs(read(localStorage,'zr-session',null));
let playingVideo=null,cachingVideoSource=null;const videoCacheErrors=new Map();
let tab='bookmarks',savedVideos=[],busy=false,offline=false,toastTimer,playerObjectURL=null;
const t=(zh,en)=>lang==='zh'?zh:en;
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast(t('浏览器无法保存资料，请检查存储权限。','Could not save. Check browser storage permissions.'));return false}}
function resolve(value){const page=coreResolve(value);if(page?.type==='search')page.url=ZeroCore.searchURL(page.query,prefs.search||'bing');return page}
function recordVisit(page){if(sessions.active.isPrivate)return;history=record(history,page);save('zr-history',history)}
function togglePrivate(){rememberPage();stopMedia();sessions.togglePrivate();persistSession();closeSheet();render()}
function reopenPage(id){rememberPage();stopMedia();if(sessions.reopen(id)){persistSession();closeSheet();render()}}
function current(){return sessions.current}
function persistSession(){save('zr-session',sessions.snapshot())}
function rememberPage(){sessions.rememberScroll(document.querySelector('.browse-content')?.scrollTop||0);if($('addressInput'))sessions.active.draft=$('addressInput').value;persistSession()}
function pageTitle(page){return page?.type==='article'?t('给注意力，留一点空白','Make room for your attention'):page?.type==='video'?t('光的涟漪','Ripples of light'):page?.title||page?.query||t('起始页','Start page')}
function newPage(){rememberPage();stopMedia();if(!sessions.create()){toast(t('最多可打开 50 个页面，请先关闭一些页面。','You can open up to 50 pages. Close a page first.'));return}persistSession();closeSheet();render();$('addressInput').focus()}
function switchPage(id){rememberPage();stopMedia();if(sessions.select(id)){persistSession();closeSheet();render()}}
function closePage(id){rememberPage();if(id===sessions.activeId)stopMedia();sessions.close(id);persistSession();render();renderSheet()}
function applyLanguage(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.querySelectorAll('[data-i]').forEach(el=>el.innerHTML=translations[el.dataset.i][lang==='zh'?0:1]);$('language').textContent=lang==='zh'?'EN':'中';$('appearance').innerHTML=icon(dark?'sun':'moon');$('phone').classList.toggle('dark',dark);$('reset').setAttribute('aria-label',t('重置预览数据','Reset preview data'));$('closePlayer').setAttribute('aria-label',t('关闭视频','Close video'))}
function setLanguage(value){lang=value;save('zr-prefs',{...prefs,lang,dark});applyLanguage();render();if(!$('sheet').hidden)renderSheet();if(ZeroReader.isOpen())ZeroReader.render()}
function setTheme(value){dark=value;save('zr-prefs',{...prefs,lang,dark});applyLanguage();if(!$('sheet').hidden)renderSheet()}
function addressBar(home=false){return `<form class="address" id="addressForm">${icon('search')}<input id="addressInput" aria-label="${t('网址或搜索','Website or search')}" placeholder="${t('输入网址或搜索','Search or enter website')}" value="${esc(sessions.active.draft)}" autocomplete="off" autocapitalize="off" spellcheck="false" enterkeyhint="go">${!home&&['article','external'].includes(current()?.type)?`<button type="button" data-action="readCurrent" aria-label="${t('阅读模式','Reader mode')}">${icon('reading')}</button>`:''}${!home?`<button type="button" data-action="pageMenu" aria-label="${t('网页操作','Page actions')}">···</button>`:''}</form>`}
function toolbar(){return `<nav class="toolbar" aria-label="${t('底部操作栏','Bottom controls')}"><button data-action="back" aria-label="${t('后退','Back')}" ${!sessions.canBack?'disabled':''}>${icon('back')}<small>${t('后退','Back')}</small></button><button data-action="forward" aria-label="${t('前进','Forward')}" ${!sessions.canForward?'disabled':''}>${icon('forward')}<small>${t('前进','Forward')}</small></button><button data-action="home" aria-label="${t('首页','Home')}">${icon('home')}<small>${t('首页','Home')}</small></button><button data-action="pages" aria-label="${t('页面管理','Manage pages')} · ${sessions.tabs.length}"><span class="tab-count">${sessions.tabs.length}</span><small>${t('页面','Pages')}</small></button><button data-action="library" aria-label="${t('资料库','Library')}">${icon('library')}<small>${t('资料库','Library')}</small></button></nav>`}
function article(){return `<article class="article"><div class="article-tag">FIELD NOTES / 001</div><h2>${t('给注意力，<br>留一点空白。','Make room<br>for your attention.')}</h2><p class="lede">${t('当每一个角落都被填满，<br>留白就成了一种温柔的选择。','When every corner asks for something,<br>empty space becomes a quiet kindness.')}</p><div class="rule"></div><p>${t('我们打开浏览器，是为了找到一个答案，读完一篇文章，或看一段喜欢的视频。沿途的噪音，却常常让我们忘了出发的理由。','We open a browser to find an answer, finish an essay, or watch something we love. Somewhere along the way, we often lose sight of why we came.')}</p><div class="pullquote">${t('简单，是让重要的事<br>自然浮现。','Simplicity makes room<br>for what matters.')}</div><p>${t('zero red 从一个输入框开始。没有信息流，没有推荐，没有未读数字。你决定去哪里，也决定什么时候停下来。','zero red begins with a single field. No feed, no recommendations, no unread counts. You decide where to go, and when to pause.')}</p><p>${t('把喜欢的网页放进书签，把还想再看的片刻保存下来。其余的，交给留白。','Keep a page you love. Save a moment for later. Leave a little space for everything else.')}</p><button class="secondary" data-action="video">${icon('video')}${t('看看视频体验','Explore the video experience')}</button><p class="foot">${t('内置阅读示例 · 交互演示<br>可在资料库收藏此页。','Built-in reading demo · interactive preview<br>You can bookmark this page in your library.')}</p></article>`}
function searchPage(page){return `<div class="article-tag">${t('搜索交互演示','SEARCH INTERACTION DEMO')}</div><h2 class="result-title">${esc(page.query)}</h2><p class="result-meta">${t('以下为内置示例结果','These are built-in example results')}</p><div class="result" role="button" tabindex="0" data-action="article"><small>zero.red / journal</small><h3>${t('给注意力，留一点空白','Make room for your attention')}</h3><p>${t('关于简单、专注，以及更安静的浏览方式。','On simplicity, focus, and a quieter way to browse.')}</p></div><div class="result" role="button" tabindex="0" data-action="video"><small>zero.red / motion</small><h3>${t('光的涟漪 — 一段可以留下的片刻','Ripples of light — a moment to keep')}</h3><p>${t('播放黑白动态影像，体验缓存与离线播放。','A monochrome motion study. Play, save, and watch offline.')}</p></div><p class="small-note">${t('想查找真实内容？可以在新标签页打开搜索。','Looking for real results? Open your search in a new tab.')}</p><a class="secondary" style="text-decoration:none" href="${esc(page.url)}" target="_blank" rel="noopener noreferrer">${icon('external')}${t('在新标签页搜索','Search in a new tab')}</a>`}
function externalPage(page){const url=new URL(page.url);return `<div class="article-tag">${t('真实网页入口','OPEN A REAL WEBSITE')}</div><div class="external-card">${icon('external')}<h2>${esc(url.hostname)}</h2><p>${t('网页预览版无法像原生浏览器一样嵌入所有网站。点击下方按钮，在新标签页打开此网页。','This preview cannot embed every website like a native browser. Open this page in a new tab below.')}</p><a class="external-link" target="_blank" rel="noopener noreferrer" href="${esc(page.url)}">${t('打开网页','Open website')} ↗</a><p class="small-note">${t('此地址已加入本地历史，也可以收藏。','This address is in your local history and can be bookmarked.')}</p></div>`}
function mediaChrome(cacheButton,expanded=false){return `<div class="media-chrome" aria-label="${t('播放器控制','Player controls')}"><div class="media-bottom"><input data-media="seek" type="range" min="0" max="1000" value="0" aria-label="${t('播放进度','Playback position')}"><div class="media-buttons"><button data-media="play" aria-label="${t('播放','Play')}"></button><span class="media-time">0:00 / 0:00</span><details class="media-settings"><summary aria-label="${t('视频设置','Video settings')}">···</summary><div class="media-settings-panel"><button data-media="mute" aria-label="${t('静音','Mute')}"></button><label>${t('倍速','Speed')}<select data-media="rate" aria-label="${t('播放速度','Playback speed')}">${[.5,1,1.25,1.5,2].map(value=>`<option value="${value}" ${value===1?'selected':''}>${value}×</option>`).join('')}</select></label><button data-media="pip">${t('画中画','Picture in Picture')}</button><button data-media="airplay">${t('投屏 / AirPlay','Cast / AirPlay')}</button><label class="media-caption-import">${t('导入 SRT / VTT 字幕','Import SRT / VTT captions')}<input data-media="captions" type="file" accept=".srt,.vtt"></label></div></details>${cacheButton}<button data-media="expand" aria-label="${t(expanded?'全屏':'展开播放',expanded?'Fullscreen':'Expand player')}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/></svg></button></div></div></div>`}
let inlineMediaController;
function bindMediaPlayers(){const frame=$('inlineVideo')?.closest('.video-art');if(frame)inlineMediaController=ZeroMedia.bind(frame,{translate:t,expand:expandVideo});const full=$('fullPlayer').closest('.player-video-frame');if(!full.querySelector('.media-chrome')){const cache=$('cachePlayingVideo');cache.remove();full.insertAdjacentHTML('beforeend',mediaChrome(cache.outerHTML,true));$('cachePlayingVideo').onclick=cacheCurrentVideo}ZeroMedia.bind(full,{translate:t})}
function videoPage(){const cached=savedVideos.some(v=>v.id==='sample');return `<article class="video-page"><div class="article-tag">MOTION STUDY / 001</div><h2>${t('光的涟漪','Ripples of light')}</h2><p>${t('给目光，一次短暂的停留。','A brief pause for your eyes.')}</p><div class="video-art"><video id="inlineVideo" src="sample.mp4" controls playsinline preload="metadata" aria-label="${t('黑白动态视频示例','Monochrome motion video demo')}"></video>${mediaChrome(`<button id="cacheCurrentVideo" class="video-overlay-cache" data-action="cacheCurrentVideo" aria-label="${t('缓存当前视频','Save current video')}">${icon(cached?'check':'download')}</button>`)}<span class="sr-only" id="videoCacheStatus" role="status"></span></div><div class="video-stats"><span>00:08 · MONOCHROME</span><span>MP4 / H.264</span></div><span class="pill">${t('内置视频示例','BUILT-IN VIDEO DEMO')}</span><p>${t('缓存会将视频保存到当前浏览器。之后可从「资料库 → 视频」播放，也可以开启离线体验，验证无需重新下载。','Saving stores a copy in this browser. Play it from Library → Videos, or turn on offline preview to use only saved files.')}</p><button class="secondary" data-action="videos">${icon('library')}${t('打开视频资料库','Open video library')}</button></article>`}
function render(){ZeroMedia.dispose($('inlineVideo')?.closest('.video-art'));const page=current();$('app').innerHTML=(page?`<div class="browse-address">${addressBar()}</div><div class="browse-content">${page.type==='article'?article():page.type==='search'?searchPage(page):page.type==='video'?videoPage():externalPage(page)}</div>`:`<div class="home ${sessions.active.isPrivate?'private-home':''}">${sessions.active.isPrivate?`<span class="private-indicator">${t('无痕浏览','PRIVATE BROWSING')}</span>`:''}${addressBar(true)}</div>`)+toolbar();$('addressForm').addEventListener('submit',e=>{e.preventDefault();const page=resolve($('addressInput').value);if(page)navigate(page)});$('addressInput').addEventListener('input',()=>{sessions.active.draft=$('addressInput').value});const content=document.querySelector('.browse-content');if(content)content.scrollTop=page?.scrollY||0;if(content)content.style.zoom=String(prefs.zoom||1);bindMediaPlayers();updateVideoCacheUI()}
function navigate(page){ZeroTools.closeFind();rememberPage();stopMedia();page={...page};if(page.type==='article')page.title=t('给注意力，留一点空白','Make room for your attention');else if(page.type==='video')page.title=t('光的涟漪','Ripples of light');else if(page.type==='search')page.title=page.query;else page.title=new URL(page.url).hostname;sessions.navigate(page);persistSession();recordVisit(page);render();closeSheet()}
function movePage(offset){rememberPage();stopMedia();if(sessions.move(offset)){persistSession();if(current()){recordVisit(current())}render()}}
function stopMedia(){document.querySelectorAll('video').forEach(video=>video.pause())}
function closeSheet(){$('sheet').hidden=true;$('app').inert=false}
function showSheet(value){rememberPage();tab=value;$('sheet').setAttribute('aria-label',value==='pages'?t('页面管理','Manage pages'):t('资料库','Library'));if(value==='pages')stopMedia();$('sheet').hidden=false;$('app').inert=true;renderSheet();refreshVideos();if(value==='reading')ZeroReader.refresh()}
function row(page,index,type){return `<div class="item"><button class="item-main" data-open="${type}:${index}"><span class="item-title">${esc(page.title)}</span><span class="item-sub">${esc(page.url)}</span></button><button class="delete" data-delete="${type}:${index}" aria-label="${t('删除','Delete')}">×</button></div>`}
function empty(name,message){return `<div class="empty">${icon(name)}<p>${message}</p></div>`}
function renderSheet(){if(tab==='pages'){renderPages();return}if(tab==='tools'){$('sheet').innerHTML=ZeroTools.menuHTML();return}const labels={bookmarks:t('书签','Bookmarks'),history:t('历史','History'),videos:t('视频','Videos'),reading:t('阅读','Reading'),downloads:t('下载','Downloads'),settings:t('设置','Settings')};$('sheet').innerHTML=`<div class="sheet-handle"></div><div class="sheet-head"><strong>zero red</strong><button data-action="closeSheet">${t('完成','Done')}</button></div><div class="segments" role="tablist">${Object.entries(labels).map(([key,label])=>`<button role="tab" aria-selected="${tab===key}" data-tab="${key}" class="${tab===key?'active':''}">${label}</button>`).join('')}</div><div class="sheet-content">${sheetContent()}</div>`;
if($('langSelect'))$('langSelect').onchange=e=>setLanguage(e.target.value);if($('themeSelect'))$('themeSelect').onchange=e=>setTheme(e.target.value==='dark');if(tab==='settings')ZeroSettings.estimate();if($('offlineToggle'))$('offlineToggle').onchange=e=>{offline=e.target.checked;toast(offline?t('离线体验已开启，仅播放本地视频。','Offline preview on. Only local videos will play.'):t('已恢复在线体验。','Online preview restored.'))}}
function renderPages(){
  $('sheet').innerHTML=`<div class="sheet-handle"></div><div class="sheet-head"><strong>${t('页面','Pages')} <span class="pages-total">${sessions.tabs.length}</span></strong><button data-action="closeSheet">${t('完成','Done')}</button></div><div class="pages-mode"><button class="${!sessions.active.isPrivate?'active':''}" data-action="regularPages">${t('普通','Regular')}</button><button class="${sessions.active.isPrivate?'active':''}" data-action="privatePages">${t('无痕','Private')}</button></div><div class="sheet-content pages-content">${sessions.active.isPrivate?`<p class="small-note">${t('无痕页面不保存浏览历史，刷新后自动关闭。','Private pages do not save history and close on reload.')}</p>`:''}<div class="page-grid">${sessions.tabs.filter(item=>!!item.isPrivate===!!sessions.active.isPrivate).map((item,index)=>{const page=item.stack[item.position]||null,selected=item.id===sessions.activeId;return `<div class="page-card ${selected?'selected':''}"><button class="page-close" data-close-page="${esc(item.id)}" aria-label="${t('关闭页面','Close page')}: ${esc(pageTitle(page))}">×</button><button class="page-select" data-select-page="${esc(item.id)}" aria-label="${t('切换到','Switch to')} ${esc(pageTitle(page))}" aria-current="${selected?'page':'false'}"><div class="page-mini ${page?.type==='video'?'mini-video':''}">${!page?`<div class="mini-search">${icon('search')}<span>${t('输入网址或搜索','Search or enter website')}</span></div>`:page.type==='video'?`<div class="mini-ripple"></div><span class="mini-play">▷</span>`:`<span class="mini-kicker">${page.type==='search'?'SEARCH':page.type==='article'?'FIELD NOTES':'WEBSITE'}</span><b>${esc(pageTitle(page))}</b><span class="mini-lines"></span><span class="mini-lines short"></span><span class="mini-lines"></span><span class="mini-lines short"></span>`}</div><div class="page-card-label"><span>${esc(pageTitle(page))}</span><span class="selected-dot" aria-hidden="true"></span></div><span class="page-card-url">${esc(page?.url||'zero red')}</span></button></div>`}).join('')}</div>${!sessions.active.isPrivate&&sessions.recentlyClosed.length?`<details class="recently-closed"><summary>${t('最近关闭','Recently closed')}</summary>${sessions.recentlyClosed.map(item=>`<button data-reopen-page="${esc(item.id)}">${esc(pageTitle(item.stack[item.position]))}</button>`).join('')}</details>`:''}</div><div class="pages-footer"><button class="primary" data-action="newPage">＋ ${t('新建页面','New page')}</button><p>${t('普通页面自动保留；无痕页面仅本次会话有效。','Regular pages are saved. Private pages stay in this session only.')}</p></div>`;
}
function sheetContent(){if(tab==='downloads')return ZeroDownloads.html();if(tab==='settings')return ZeroSettings.html();if(tab==='reading')return ZeroReader.libraryHTML();if(tab==='bookmarks')return (current()?`<button class="secondary save-page" data-action="bookmark">${icon('bookmark')}${t('收藏当前网页','Bookmark this page')}</button>`:'')+(bookmarks.length?bookmarks.map((p,i)=>row(p,i,'bookmarks')).join(''):empty('bookmark',t('把喜欢的网页，留在这里。<br>打开示例网页后即可收藏。','A place for pages you love.<br>Open a page to add your first bookmark.')));
if(tab==='history')return history.length?history.map((p,i)=>row(p,i,'history')).join('')+`<button class="clear" data-action="clearHistory">${t('清空历史记录','Clear browsing history')}</button>`:empty('history',t('还没有足迹。<br>从一个好奇的问题开始。','No footprints yet.<br>Start with a little curiosity.'));

return `<div class="section-label">${t('缓存视频','SAVE A VIDEO')}</div><button class="secondary" data-action="cacheSample" ${busy?'disabled':''}>${icon('download')}${busy?t('正在缓存…','Saving…'):t('缓存内置视频示例','Save the demo video')}</button><form id="videoForm"><input class="sheet-input" id="videoURL" style="margin-top:13px" type="url" placeholder="${t('或粘贴 HTTPS MP4 链接','Or paste an HTTPS MP4 URL')}" aria-label="${t('视频链接','Video URL')}"><button class="primary" type="submit" ${busy?'disabled':''}>${t('下载并保存','Download and save')}</button></form><p class="small-note">${t('外部视频需要服务器允许跨域下载。仅支持未加密的 MP4/MOV，最大 100 MB；缓存可能被浏览器清理。','External servers must allow cross-origin downloads. Unencrypted MP4/MOV only, up to 100 MB. Browser storage may be cleared.')}</p><label class="offline-toggle"><input type="checkbox" id="offlineToggle" ${offline?'checked':''}>${t('离线体验：只播放已保存的视频','Offline preview: play saved files only')}</label><div class="section-label">${t('本地视频','LOCAL VIDEOS')} · ${savedVideos.length}</div>${savedVideos.length?savedVideos.map(v=>`<div class="item"><button class="item-main" data-play="${esc(v.id)}"><span class="item-title">${icon('video')} ${esc(v.title)}</span><span class="item-sub">${(v.size/1024/1024).toFixed(2)} MB · ${t('已保存到本地','Saved locally')}</span></button><button class="delete" data-video-delete="${esc(v.id)}" aria-label="${t('删除视频','Delete video')}">×</button></div>`).join(''):empty('video',t('缓存之后，片刻随行。','Save a moment. Take it with you.'))}`}
const storage=ZeroStorage.createStorage(indexedDB);
function dbOp(mode,action,storeName='videos'){return storage.operation(mode,action,storeName)}
async function refreshVideos(){try{const list=await dbOp('readonly',store=>store.getAll());savedVideos=list.map(({blob,...meta})=>meta);if(!$('sheet').hidden&&tab==='videos')renderSheet();updateVideoCacheUI()}catch{toast(t('无法使用视频存储，请允许浏览器保存资料。','Video storage is unavailable. Allow browser storage.'))}}
function currentVideoTarget(){const expanded=!$('playerDialog').hidden;const video=expanded?$('fullPlayer'):$('inlineVideo');return videoTarget({currentSrc:video?.currentSrc,src:video?.getAttribute('src'),cachedId:expanded?playingVideo?.cachedId:null,title:expanded?playingVideo?.title:t('光的涟漪','Ripples of light')},location.href)}
function targetIsCached(target){if(!target)return false;return !!target?.cachedId||savedVideos.some(video=>video.source===target?.source||(video.id==='sample'&&target?.source===new URL('sample.mp4',location.href).href))}
function updateVideoCacheUI(){for(const [id,expanded] of [['cacheCurrentVideo',false],['cachePlayingVideo',true]]){const button=$(id);if(!button)continue;let target;try{const video=expanded?$('fullPlayer'):$('inlineVideo');target=videoTarget({currentSrc:video?.currentSrc,src:video?.getAttribute('src'),cachedId:expanded?playingVideo?.cachedId:null,title:expanded?playingVideo?.title:null},location.href)}catch{}const cached=targetIsCached(target),saving=!!target&&cachingVideoSource===target.source;button.disabled=!target||cached||busy;button.innerHTML=icon(cached?'check':'download');button.classList.toggle('is-saving',saving);button.setAttribute('aria-label',cached?t('当前视频已缓存','Current video saved'):saving?t('正在缓存当前视频','Saving current video'):t('缓存当前视频','Save current video'));button.setAttribute('aria-busy',String(saving));const status=$(expanded?'playerCacheStatus':'videoCacheStatus');if(status)status.textContent=cached?t('可从资料库 → 视频离线播放','Available offline in Library → Videos'):saving?t('正在保存，播放不会中断','Saving without interrupting playback'):(videoCacheErrors.get(target?.source)||'')}}
async function cacheCurrentVideo(){try{const target=currentVideoTarget();if(targetIsCached(target)){toast(t('当前视频已缓存，可离线播放。','This video is already saved for offline playback.'));return}await cacheVideo(target.source,target.source===new URL('sample.mp4',location.href).href,target.title)}catch(error){toast(error.message==='no-video'?t('请先播放一个视频。','Play a video first.'):t('当前视频无法直接缓存，仅支持可下载的 MP4/MOV。','This video cannot be saved directly. Use a downloadable MP4/MOV.'))}}
function expandVideo(){const video=$('inlineVideo');if(!video)return;const target=currentVideoTarget();const time=video.currentTime||0;video.pause();playingVideo={...target,title:t('光的涟漪','Ripples of light')};$('fullPlayer').src=target.source;$('playerCaption').textContent=playingVideo.title;$('playerDialog').hidden=false;bindMediaPlayers();$('fullPlayer').onloadedmetadata=()=>{$('fullPlayer').currentTime=time};updateVideoCacheUI();$('fullPlayer').play().catch(()=>{})}
async function cacheVideo(url,isSample=false,videoTitle=null){if(busy)return;const source=new URL(url,location.href).href;if(savedVideos.some(v=>v.source===source||(isSample&&v.id==='sample'))){toast(t('此视频已缓存。','This video is already saved.'));return}if(offline){toast(t('请先关闭离线体验再下载。','Turn off offline preview before downloading.'));return}busy=true;cachingVideoSource=source;videoCacheErrors.delete(source);if(!$('sheet').hidden)renderSheet();updateVideoCacheUI();const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),90000);try{const response=await fetch(source,{signal:controller.signal,credentials:'omit',cache:'no-store'});if(!response.ok||response.status===206)throw Error(t('视频下载失败或不完整。','Video download failed or is incomplete.'));const mime=response.headers.get('content-type')||'';if(!/^video\/(mp4|quicktime|x-m4v)(;|$)/i.test(mime))throw Error(t('此链接不是可缓存的 MP4/MOV 视频。','This link is not a downloadable MP4/MOV video.'));const limit=100*1024*1024;if(Number(response.headers.get('content-length'))>limit)throw Error(t('视频超过 100 MB 限制。','Video exceeds the 100 MB limit.'));const reader=response.body?.getReader();if(!reader)throw Error(t('当前浏览器不支持此下载方式。','This browser does not support streaming downloads.'));let size=0,chunks=[];while(true){const {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>limit){await reader.cancel();throw Error(t('视频超过 100 MB 限制。','Video exceeds the 100 MB limit.'))}chunks.push(value)}if(!size)throw Error(t('视频文件为空。','Video file is empty.'));const blob=new Blob(chunks,{type:mime}),id=isSample?'sample':crypto.randomUUID();const title=videoTitle||(isSample?t('光的涟漪','Ripples of light'):decodeURIComponent(new URL(source).pathname.split('/').pop()||'Video'));await dbOp('readwrite',store=>store.put({id,title,size,blob,source,date:Date.now()}));toast(t('当前视频已缓存，可从资料库离线播放。','Current video saved for offline playback.'));await refreshVideos()}catch(error){const message=error.name==='AbortError'?t('下载超时，请重试。','Download timed out. Try again.'):error instanceof TypeError?t('无法下载，视频服务器可能未允许跨域访问。','Download unavailable. The server may not allow cross-origin access.'):error.message;videoCacheErrors.set(source,message);toast(message);for(const id of ['videoCacheStatus','playerCacheStatus'])if($(id))$(id).textContent=message}finally{clearTimeout(timeout);busy=false;cachingVideoSource=null;if(!$('sheet').hidden)renderSheet();updateVideoCacheUI()}}
async function playSaved(id){try{const video=await dbOp('readonly',store=>store.get(id));if(!video)throw Error(t('本地文件不存在，请重新缓存。','Local file is missing. Save it again.'));stopMedia();playingVideo={cachedId:video.id,title:video.title};$('fullPlayer').onloadedmetadata=null;if(playerObjectURL)URL.revokeObjectURL(playerObjectURL);playerObjectURL=URL.createObjectURL(video.blob);$('fullPlayer').src=playerObjectURL;$('playerCaption').textContent=video.title+' · '+t('从本地播放','Playing from local storage');$('playerDialog').hidden=false;bindMediaPlayers();$('closePlayer').focus();updateVideoCacheUI();$('fullPlayer').play().catch(()=>{});}catch(e){toast(e.message)}}
function closePlayer(){$('fullPlayer').pause();$('fullPlayer').removeAttribute('src');$('fullPlayer').load();$('playerDialog').hidden=true;if(playerObjectURL)URL.revokeObjectURL(playerObjectURL);playerObjectURL=null;playingVideo=null;$('fullPlayer').onloadedmetadata=null;updateVideoCacheUI()}
const actions={pageMenu:()=>ZeroTools.pageMenu(),sharePage:()=>ZeroTools.share(),copyPage:()=>ZeroTools.copy(),findPage:()=>{closeSheet();ZeroTools.find()},savePageFile:()=>{const page=current();if(page?.url.startsWith('https:')){showSheet('downloads');ZeroDownloads.start(page.url)}else toast(t('请打开一个 HTTPS 文件链接。','Open an HTTPS file URL.'))},togglePrivate,regularPages:()=>{if(sessions.active.isPrivate)sessions.togglePrivate();persistSession();render();renderSheet()},privatePages:()=>{if(!sessions.active.isPrivate)sessions.togglePrivate();persistSession();render();renderSheet()},article:()=>navigate({type:'article',url:'zero:read'}),video:()=>navigate({type:'video',url:'zero:video'}),back:()=>movePage(-1),forward:()=>movePage(1),reload:()=>{rememberPage();closeSheet();render();toast(t('页面已刷新','Page refreshed'))},home:()=>{rememberPage();stopMedia();sessions.navigate(null);persistSession();render()},pages:()=>showSheet('pages'),newPage,readCurrent:()=>ZeroReader.readCurrent(),reading:()=>showSheet('reading'),library:()=>showSheet('bookmarks'),videos:()=>showSheet('videos'),closeSheet,bookmark:()=>{const page=current();if(page){bookmarks=bookmark(bookmarks,page);save('zr-bookmarks',bookmarks);renderSheet();toast(t('已加入书签','Bookmarked'))}},clearHistory:()=>{if(confirm(t('清空所有历史记录？','Clear all browsing history?'))){history=[];sessions.recentlyClosed=[];persistSession();save('zr-history',history);renderSheet()}},cacheCurrentVideo,expandVideo,cacheSample:()=>cacheVideo('sample.mp4',true)};
document.addEventListener('click',async e=>{const reopen=e.target.closest('[data-reopen-page]');if(reopen){reopenPage(reopen.dataset.reopenPage);return}const select=e.target.closest('[data-select-page]');if(select){switchPage(select.dataset.selectPage);return}const close=e.target.closest('[data-close-page]');if(close){closePage(close.dataset.closePage);return}const action=e.target.closest('[data-action]');if(action){actions[action.dataset.action]?.();return}const tabButton=e.target.closest('[data-tab]');if(tabButton){tab=tabButton.dataset.tab;renderSheet();return}const item=e.target.closest('[data-open]');if(item){const [kind,index]=item.dataset.open.split(':');navigate({...({bookmarks,history}[kind][Number(index)])});return}const del=e.target.closest('[data-delete]');if(del){const [kind,index]=del.dataset.delete.split(':');const array=kind==='bookmarks'?bookmarks:history;array.splice(Number(index),1);save('zr-'+kind,array);renderSheet();return}const video=e.target.closest('[data-play]');if(video){playSaved(video.dataset.play);return}const remove=e.target.closest('[data-video-delete]');if(remove){try{await dbOp('readwrite',store=>store.delete(remove.dataset.videoDelete));await refreshVideos()}catch{toast(t('删除失败，请重试。','Could not delete. Try again.'))}return}const demo=e.target.closest('[data-demo]');if(demo){if(demo.dataset.demo==='search')navigate(resolve(t('极简生活','the art of less')));else actions[demo.dataset.demo]();}});
document.addEventListener('submit',e=>{if(e.target.id==='videoForm'){e.preventDefault();try{const url=new URL($('videoURL').value.trim());if(url.protocol!=='https:')throw Error(t('请输入 HTTPS 视频链接。','Enter an HTTPS video URL.'));cacheVideo(url.href)}catch(error){toast(error.message)}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('playerDialog').hidden)closePlayer();else closeSheet()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('.result')){e.preventDefault();e.target.click()}});
$('closePlayer').onclick=closePlayer;$('cachePlayingVideo').onclick=cacheCurrentVideo;$('fullPlayer').onerror=()=>{$('playerCaption').textContent=t('设备无法播放此视频格式，请尝试 MP4/H.264。','This device cannot play this format. Try MP4/H.264.')};$('language').onclick=()=>setLanguage(lang==='zh'?'en':'zh');$('appearance').onclick=()=>setTheme(!dark);$('reset').onclick=async()=>{if(!confirm(t('删除本预览的书签、历史、阅读文档和缓存视频？','Delete bookmarks, history, saved documents and videos for this preview?')))return;try{await ZeroReader.reset();await ZeroDownloads.clear();await dbOp('readwrite',store=>store.clear());bookmarks=[];history=[];savedVideos=[];save('zr-bookmarks',[]);save('zr-history',[]);offline=false;sessions.tabs=[];sessions.recentlyClosed=[];sessions.create(false);persistSession();stopMedia();render();closeSheet();toast(t('预览数据已重置','Preview data reset'))}catch{toast(t('重置失败，请检查存储权限。','Reset failed. Check browser storage permissions.'))}};
window.addEventListener('pagehide',rememberPage);
document.addEventListener('visibilitychange',()=>{if(document.hidden)rememberPage()});
applyLanguage();render();refreshVideos();ZeroReader.init();ZeroTools.init();ZeroDownloads.init();ZeroSettings.init();
if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
